import { ScrollView, StyleSheet, Text, View } from "react-native";
import type { ReactNode } from "react";
import type { StyleProp, TextStyle, ViewProps, ViewStyle } from "react-native";
import { metrics, useTokens } from "../lib/rn-tokens";

export interface TimelineEvent {
  id: string;
  /** When it happened: a timestamp in milliseconds or an ISO string. */
  at: string | number;
  actor?: string;
  title: string;
  meta?: string;
  detail?: ReactNode;
  tone?: "neutral" | "success" | "danger";
}

export interface TimelineProps extends Omit<ViewProps, "children"> {
  events: TimelineEvent[];
  /** The moment relative times are measured from, in milliseconds. Pass it in so server and client agree. */
  now: number;
  label: string;
  locale?: string;
  maxHeight?: number;
  /** Extend the inner, named parts of the timeline: event, dot, line, title, meta or time. The React Native counterpart of `classNames`. */
  styles?: {
    event?: StyleProp<ViewStyle>;
    dot?: StyleProp<ViewStyle>;
    line?: StyleProp<ViewStyle>;
    title?: StyleProp<TextStyle>;
    meta?: StyleProp<TextStyle>;
    time?: StyleProp<TextStyle>;
  };
}

function ago(at: string | number, now: number, locale: string): string {
  const seconds = Math.round((new Date(at).getTime() - now) / 1000);
  const formatter = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });
  for (const [unit, size] of [["day", 86400], ["hour", 3600], ["minute", 60]] as const) {
    if (Math.abs(seconds) >= size) return formatter.format(Math.round(seconds / size), unit);
  }
  return formatter.format(seconds, "second");
}

export function Timeline({ events, now, label, locale = "en-US", maxHeight, style, styles: parts, ...props }: TimelineProps) {
  const tokens = useTokens();
  const sorted = [...events].sort((a, b) => new Date(b.at).getTime() - new Date(a.at).getTime());

  return (
    <View {...props} accessibilityRole="list" accessibilityLabel={label} style={[{ alignSelf: "stretch" }, style]}>
      <ScrollView style={{ maxHeight }} nestedScrollEnabled>
        {sorted.map((event, index) => {
          const color = event.tone === "success" ? tokens.success : event.tone === "danger" ? tokens.danger : tokens.borderStrong;
          return (
            <View key={event.id} style={[local.event, parts?.event]}>
              <View style={local.rail}>
                <View style={[local.dot, { backgroundColor: color }, parts?.dot]} />
                {index < sorted.length - 1 ? <View style={[local.line, { backgroundColor: tokens.border }, parts?.line]} /> : null}
              </View>
              <View style={local.copy}>
                <Text style={[{ color: tokens.foreground, fontSize: metrics.text.sm }, parts?.title]}>
                  {event.actor ? <Text style={{ fontWeight: "600" }}>{event.actor} </Text> : null}
                  {event.title}
                </Text>
                <Text style={[{ color: tokens.textMuted, fontSize: metrics.text.xs }, parts?.time]}>{ago(event.at, now, locale)}</Text>
                {event.meta ? <Text style={[{ color: tokens.textSecondary, fontSize: metrics.text.xs }, parts?.meta]}>{event.meta}</Text> : null}
                {event.detail}
              </View>
            </View>
          );
        })}
      </ScrollView>
    </View>
  );
}

const local = StyleSheet.create({
  event: { flexDirection: "row", gap: metrics.space[3] },
  rail: { alignItems: "center", width: 12 },
  dot: { width: 10, height: 10, marginTop: 5, borderRadius: 5 },
  line: { flex: 1, width: 2, marginVertical: 4, borderRadius: 1 },
  copy: { flex: 1, gap: 2, paddingBottom: metrics.space[4] },
});

export default Timeline;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
